#define MAXN 1000
#define MAXM 2000

typedef struct {
    int to;
    int next;
} Edge;

Edge edges[MAXM];
int head[MAXN], edgeCnt;
int color[MAXN];
int n, m;

void init() {
    edgeCnt = 0;
    memset(head, -1, sizeof(head));
    memset(color, -1, sizeof(color));
}

void addEdge(int u, int v) {
    edges[edgeCnt].to = v;
    edges[edgeCnt].next = head[u];
    head[u] = edgeCnt++;
    edges[edgeCnt].to = u;
    edges[edgeCnt].next = head[v];
    head[v] = edgeCnt++;
}

int dfs(int u, int c) {
    color[u] = c;
    for (int i = head[u]; i != -1; i = edges[i].next) {
        int v = edges[i].to;
        if (color[v] == -1) {
            if (!dfs(v, 1 - c)) return 0;
        } else if (color[v] == c) {
            return 0;
        }
    }
    return 1;
}

int isBipartite() {
    for (int i = 0; i < n; i++) {
        if (color[i] == -1) {
            if (!dfs(i, 0)) return 0;
        }
    }
    return 1;
}

int main() {
    while (scanf("%d %d", &n, &m) == 2) {
