        init();
        for (int i = 0; i < m; i++) {
            int u, v;
            scanf("%d %d", &u, &v);
            addEdge(u, v);
        }
        if (isBipartite()) {
            printf("yes\n");
        } else {
            printf("no\n");
        }
    }
    return 0;
