static int cmp_int(const void *a, const void *b) {
    int x = *(const int *)a;
    int y = *(const int *)b;
    return (x > y) - (x < y);
}

int main(void) {
    int n, m;

    while (scanf("%d %d", &n, &m) == 2) {
        Edge *edges = (Edge *)malloc(sizeof(Edge) * (m > 0 ? m : 1));
        int *deg = (int *)calloc((n > 0 ? n : 1), sizeof(int));
        int possible = 1;

        for (int i = 0; i < m; i++) {
            int a, b;
            scanf("%d %d", &a, &b);
            a--; b--;
            edges[i].u = a;
            edges[i].v = b;

            if (a == b) possible = 0;          // loop not allowed for line graph drawing
            if (a >= 0 && a < n) deg[a]++;
            if (b >= 0 && b < n) deg[b]++;
        }

        /* A graph can be drawn on a line iff every connected component is a path
           or an isolated vertex. Equivalently:
           - no vertex has degree > 2
           - the graph has no cycle
        */

        for (int i = 0; i < n; i++) {
            if (deg[i] > 2) {
                possible = 0;
                break;
            }
        }

        if (possible) {
            int *parent = (int *)malloc(sizeof(int) * (n > 0 ? n : 1));
            int *rank = (int *)calloc((n > 0 ? n : 1), sizeof(int));
            for (int i = 0; i < n; i++) parent[i] = i;

            int find(int x) {
                while (parent[x] != x) {
                    parent[x] = parent[parent[x]];
                    x = parent[x];
                }
                return x;
            }

            void unite(int a, int b) {
                int ra = find(a), rb = find(b);
                if (ra == rb) return;
                if (rank[ra] < rank[rb]) parent[ra] = rb;
                else if (rank[ra] > rank[rb]) parent[rb] = ra;
                else {
                    parent[rb] = ra;
                    rank[ra]++;
                }
            }

            /* Detect duplicate edges and cycles */
            int *arr = (int *)malloc(sizeof(int) * (2 * (m > 0 ? m : 1)));
            for (int i = 0; i < m; i++) {
                int u = edges[i].u, v = edges[i].v;
                if (u > v) {
                    int t = u; u = v; v = t;
                }
                arr[2 * i] = u;
                arr[2 * i + 1] = v;
            }

            /* sort pairs lexicographically by encoding */
            long long *code = (long long *)malloc(sizeof(long long) * (m > 0 ? m : 1));
            for (int i = 0; i < m; i++) {
                code[i] = (long long)arr[2 * i] * n + arr[2 * i + 1];
            }
            int cmp_ll(const void *a, const void *b) {
                long long x = *(const long long *)a;
                long long y = *(const long long *)b;
                return (x > y) - (x < y);
            }
            qsort(code, m, sizeof(long long), cmp_ll);
            for (int i = 1; i < m; i++) {
                if (code[i] == code[i - 1]) {
                    possible = 0;              // multiple edges not allowed
                    break;
                }
            }
            free(code);
            free(arr);

            if (possible) {
                for (int i = 0; i < m; i++) {
                    int u = edges[i].u, v = edges[i].v;
                    int ru = find(u), rv = find(v);
                    if (ru == rv) {
                        possible = 0;          // cycle exists
                        break;
                    }
                    unite(ru, rv);
                }
            }

            free(parent);
            free(rank);
        }

        printf("%s\n", possible ? "yes" : "no");

        free(edges);
        free(deg);
    }

    return 0;
}

