public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line;
        while ((line = br.readLine()) != null) {
            line = line.trim();
            if (line.isEmpty()) continue;
            String[] parts = line.split(" ");
            int n = Integer.parseInt(parts[0]);
            int m = Integer.parseInt(parts[1]);
            if (n == 0 && m == 0) break;

            List<int[]> edges = new ArrayList<>();
            for (int i = 0; i < m; i++) {
                String[] edgeParts = br.readLine().split(" ");
                int u = Integer.parseInt(edgeParts[0]);
                int v = Integer.parseInt(edgeParts[1]);
                edges.add(new int[]{u, v});
            }

            // Build adjacency list
            List<Integer>[] adj = new ArrayList[n];
            for (int i = 0; i < n; i++) adj[i] = new ArrayList<>();
            for (int[] e : edges) {
                int u = e[0], v = e[1];
                adj[u].add(v);
                adj[v].add(u);
            }

            // Check if graph is a collection of paths (degree <= 2) and no cycles
            boolean possible = true;
            int[] degree = new int[n];
            for (int i = 0; i < n; i++) {
                degree[i] = adj[i].size();
                if (degree[i] > 2) {
                    possible = false;
                    break;
                }
            }
            if (!possible) {
                System.out.println("no");
                continue;
            }

            // Check for cycles (in a graph with max degree 2, cycles are simple cycles)
            boolean[] visited = new boolean[n];
            for (int i = 0; i < n; i++) {
                if (!visited[i]) {
                    // BFS/DFS to detect cycle
                    int nodeCount = 0;
                    int edgeCount = 0;
                    Queue<Integer> q = new LinkedList<>();
                    q.add(i);
                    visited[i] = true;
                    while (!q.isEmpty()) {
                        int u = q.poll();
                        nodeCount++;
                        for (int v : adj[u]) {
                            edgeCount++;
                            if (!visited[v]) {
                                visited[v] = true;
                                q.add(v);
                            }
                        }
                    }
                    // Each edge counted twice
                    edgeCount /= 2;
                    // In a tree (path) edges = nodes - 1, in a cycle edges = nodes
                    if (edgeCount == nodeCount) {
                        // It's a cycle, not allowed on a line
                        possible = false;
                        break;
                    }
                }
            }

            System.out.println(possible ? "yes" : "no");
        }
    }
}

