public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        StringBuilder out = new StringBuilder();

        while (true) {
            int n = fs.nextInt();
            int m = fs.nextInt();
            if (n == 0 && m == 0) break;

            int[] deg = new int[n];
            boolean ok = true;

            for (int i = 0; i < m; i++) {
                int a = fs.nextInt();
                int b = fs.nextInt();
                // assume vertices are numbered 1..n
                a--;
                b--;
                if (a == b) ok = false; // self-loop cannot be drawn on a line
                if (a >= 0 && a < n) deg[a]++;
                if (b >= 0 && b < n) deg[b]++;
            }

            // A graph can be embedded on a line iff every vertex degree <= 2.
            // Then each connected component is a path or a cycle, both drawable on a line.
            for (int i = 0; i < n; i++) {
                if (deg[i] > 2) {
                    ok = false;
                    break;
                }
            }

            out.append(ok ? "yes" : "no").append('\n');
        }

        System.out.print(out.toString());
    }
}

