import sys

def is_linear_graph(n, edges):
    # For drawing on a line with straight segments and no overlaps/intersections
    # except at common endpoints, each connected component must be a simple path
    # or an isolated vertex. Equivalently:
    # - no vertex has degree > 2
    # - the graph has no cycle
    #
    # Since the input is a simple graph, this is enough.

    parent = list(range(n))
    rank = [0] * n
    deg = [0] * n

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra == rb:
            return False  # cycle detected
        if rank[ra] < rank[rb]:
            parent[ra] = rb
        elif rank[ra] > rank[rb]:
            parent[rb] = ra
        else:
            parent[rb] = ra
            rank[ra] += 1
        return True

    for u, v in edges:
        deg[u] += 1
        deg[v] += 1
        if deg[u] > 2 or deg[v] > 2:
            return False
        if not union(u, v):
            return False

    return True

